export function buscarEmpleadoTAT(cedula) {
  const clean = String(cedula).replace(/[^0-9]/g, '');
  return RETENCIONES_TAT_2025.find(e => String(e.id).replace(/[^0-9]/g, '') === clean) || null;
}

export function getNombreCompletoTAT(emp) {
  return [emp.nombre1, emp.nombre2, emp.apellido1, emp.apellido2].filter(Boolean).join(' ');
}
